//! Two `BufferedUart`s bridged: the virtual COM port (SERCOM1, PB00/PB01,
//! 38,400 baud) to SERCOM0 (PA04 TX / PA05 RX, 115,200 baud) and back. With
//! PA04 jumpered to PA05, what the host sends comes straight back: both
//! SERCOMs' interrupts, rings and baud rates at once.

#![no_std]
#![no_main]
#![allow(clippy::used_underscore_binding, reason = "in code generated by embassy_executor::main")]

use embassy_executor::Spawner;
use embassy_futures::join::join;
use panic_halt as _;
use pic32c_hal::gpio::{Level, Output, Pull};
use pic32c_hal::uart::{self, BufferedUart};
use pic32c_hal::{bind_interrupts, peripherals};
use static_cell::ConstStaticCell;

bind_interrupts!(struct Irqs {
    SERCOM0 => uart::InterruptHandler<peripherals::SERCOM0>;
    SERCOM1 => uart::InterruptHandler<peripherals::SERCOM1>;
});

static CDC_TX: ConstStaticCell<[u8; 256]> = ConstStaticCell::new([0; 256]);
static CDC_RX: ConstStaticCell<[u8; 256]> = ConstStaticCell::new([0; 256]);
static LINK_TX: ConstStaticCell<[u8; 256]> = ConstStaticCell::new([0; 256]);
static LINK_RX: ConstStaticCell<[u8; 256]> = ConstStaticCell::new([0; 256]);

fn config(baud: u32) -> uart::Config {
    let mut config = uart::Config::default();
    config.baudrate = baud;
    config.rx_pull = Pull::Up;
    config
}

#[embassy_executor::main]
async fn main(_spawner: Spawner) {
    let p = pic32cm_pl10_curiosity_nano::init();
    let mut led = Output::new(p.PB02, Level::High);
    let cdc = BufferedUart::new(p.SERCOM1, p.PB00, p.PB01, Irqs, CDC_TX.take(), CDC_RX.take(), config(38_400)).unwrap();
    let link = BufferedUart::new(p.SERCOM0, p.PA04, p.PA05, Irqs, LINK_TX.take(), LINK_RX.take(), config(115_200)).unwrap();
    let (mut cdc_tx, mut cdc_rx) = cdc.split();
    let (mut link_tx, mut link_rx) = link.split();
    led.set_low();
    let out = async {
        let mut buffer = [0u8; 64];
        loop {
            if let Ok(n) = cdc_rx.read(&mut buffer).await {
                let _ = link_tx.write_all(&buffer[..n]).await;
            }
        }
    };
    let back = async {
        let mut buffer = [0u8; 64];
        loop {
            if let Ok(n) = link_rx.read(&mut buffer).await {
                let _ = cdc_tx.write_all(&buffer[..n]).await;
            }
        }
    };
    join(out, back).await;
}
